mapper.select:
select * from ( select
(IFNULL(CLASS1_PLAN, 0) + IFNULL(CLASS2_PLAN, 0) + IFNULL(CLASS3_PLAN, 0)) as daily_total_qty, TRUNCATE(IFNULL(CLASS1_PLAN_NUM, 0) + IFNULL(CLASS2_PLAN_NUM, 0) + IFNULL(CLASS3_PLAN_NUM, 0), 1) as daily_total_qty_num, b.MONTH_PLAN_QTY as month_plan, CEILING(b.MONTH_REMAIN_QTY) as month_plan_os, TRUNCATE(f.class1_finish_qty, 0) as class1_finish_qty, TRUNCATE(f.class2_finish_qty, 0) as class2_finish_qty, c.COLOR_TYPE, c.COLOR_CODE, d.notes, log.change_machine, log.change_mid_plan, log.change_night_plan, log.change_day_plan from t_gdyy_schedule_result a LEFT JOIN ( select MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY from T_GDYY_MONTH_PLAN_SURPLUS where YEAR=#{year,jdbcType=VARCHAR} and MONTH= #{month,jdbcType=VARCHAR} and del_flag = '0' ) b on a.BIG_ROLL_CODE=b.MATERIAL_CODE LEFT JOIN T_GDYY_DAY_FINISH_QTY f ON a.order_no = f.order_no and f.del_flag = '0' LEFT JOIN T_GDYY_BIG_ROLL_COLOR c ON a.BIG_ROLL_CODE = c.BIG_ROLL_CODE AND c.STATUS = '0' AND c.DEL_FLAG = '0' LEFT JOIN ( SELECT BIG_ROLL_CODE,GROUP_CONCAT(notes order by notes SEPARATOR ',') notes FROM T_GDYY_NOTE WHERE STATUS = '0' AND DEL_FLAG = '0' AND IFNULL(START_TIME, STR_TO_DATE('0001-01-01', '%Y-%m-%d')) <= #{scheduleDate} AND IFNULL(END_TIME, STR_TO_DATE('9999-12-31', '%Y-%m-%d')) >= #{scheduleDate} GROUP BY BIG_ROLL_CODE ) d ON d.BIG_ROLL_CODE = a.BIG_ROLL_CODE LEFT JOIN (/*调度员操作日志，判断调度员是否有做“转机台”或“调量”操作*/ SELECT schedule_id, max(IF(BEFORE_MACHINE_ID = AFTER_MACHINE_ID,0,1)) change_machine, max(IF(BEFORE_MID_PLAN = AFTER_MID_PLAN,0,1)) change_mid_plan, max(IF(BEFORE_NIGHT_PLAN = AFTER_NIGHT_PLAN,0,1)) change_night_plan, max(IF(BEFORE_DAY_PLAN = AFTER_DAY_PLAN,0,1)) change_day_plan FROM T_GDYY_DISPATCHER_LOG where schedule_date = #{scheduleDate} group by schedule_id ) log ON a.id = log.schedule_id where a.del_flag = '0' and a.schedule_date = #{scheduleDate}
and INSTR(a.big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0
and production_status = #{productionStatus} and a.is_release = #{isRelease} and a.id in #{scheduleId} order by a.CREATE_TIME desc ) t
order by ${orderStr}

select count(1)
from t_schedule_publish_record
where procedure_code = #{procedureCode,jdbcType=VARCHAR}
  and schedule_date = #{scheduleDate,jdbcType=DATE}
  and publish_status = '1'
  and del_flag = '0'

select count(1) from t_gdyy_schedule_result
where del_flag = '0'
and schedule_date = #{scheduleDate}
and big_roll_code = #{bigRollCode}
and MACHINE_CODE = #{machineCode}
and id != #{id}

select count(1) from t_gdyy_schedule_result
where del_flag = 0 and schedule_date = #{scheduleDate,jdbcType=DATE}
  and (IS_RELEASE = 3 or IS_RELEASE = 4)

mapper.update:
update t_gdyy_schedule_result
set IS_RELEASE = #{isRelease, jdbcType=VARCHAR}
,PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = now()
where del_flag = 0 and schedule_date = #{scheduleDate,jdbcType=DATE}
  and (IS_RELEASE = 3 or IS_RELEASE = 4)

update t_gdyy_schedule_result set IS_RELEASE = #{status}
, PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = now()
where id in

    #{id}

update t_gdyy_schedule_result set del_flag = NULL
where id in

    #{id}

UPDATE t_schedule_publish_record
SET PUBLISH_STATUS = #{status}
WHERE data_version = #{dataVersion}
  AND del_flag = 0

mapper.select:
SELECT schedule_date,
SUM(class1_plan) as day_plan_qty,
SUM(class2_plan) as night_plan_qty,
SUM(stock_qty) as stock_qty
FROM t_gdyy_schedule_result
WHERE schedule_date = #{scheduleDate}

    and INSTR(big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0

and production_status = #{productionStatus}
and is_release = #{isRelease}

SELECT SUM(class2_plan) as night_plan_qty
FROM t_gdyy_schedule_result
WHERE schedule_date = DATE_SUB(#{scheduleDate}, INTERVAL 1 DAY)

    and INSTR(big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0

and production_status = #{productionStatus}
and is_release = #{isRelease}
